const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Measuring AI Ability to Complete Long Software Tasks";
pres.author = "METR (Model Evaluation & Threat Research)";

// Palette: Deep navy dominant, ice blue support, electric teal accent
const C = {
  navyDark: "0D1B2A",    // dominant dark bg
  navy:     "1A2E45",    // secondary bg
  teal:     "00B4D8",    // accent / highlights
  tealDark: "0077A8",    // darker teal
  ice:      "CAE9FF",    // light text on dark
  white:    "FFFFFF",
  offWhite: "F0F4F8",
  slate:    "64748B",
  slateLight: "94A3B8",
  cardBg:   "142030",    // card background on dark slides
  cardBg2:  "F8FAFC",    // card background on light slides
  gold:     "F5A623",    // special callout
  green:    "22C55E",
  red:      "EF4444",
};

const FONT_HEAD = "Calibri";
const FONT_BODY = "Calibri";

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.18 });

// ─────────────────────────────────────────────
// SLIDE 1: Title Slide
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  // Left teal accent bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Subtle grid pattern overlay (decorative rectangle)
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 0, w: 3.5, h: 5.625,
    fill: { color: "FFFFFF", transparency: 97 }, line: { color: C.teal, transparency: 85, width: 0.5 }
  });

  // METR label
  sl.addText("MODEL EVALUATION & THREAT RESEARCH (METR) — MARCH 2025", {
    x: 0.45, y: 0.38, w: 9.1, h: 0.28,
    fontFace: FONT_BODY, fontSize: 9, color: C.teal, bold: true,
    charSpacing: 2, align: "left", margin: 0
  });

  // Main title
  sl.addText("Measuring AI Ability to Complete Long Software Tasks", {
    x: 0.45, y: 0.85, w: 8.6, h: 1.55,
    fontFace: FONT_HEAD, fontSize: 36, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // Headline stat box
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 2.55, w: 7.0, h: 0.95,
    fill: { color: C.teal, transparency: 88 }, line: { color: C.teal, width: 1.5 }
  });
  sl.addText("50% TASK-COMPLETION TIME HORIZON DOUBLING EVERY ~7 MONTHS", {
    x: 0.55, y: 2.60, w: 6.8, h: 0.85,
    fontFace: FONT_HEAD, fontSize: 17, color: C.teal, bold: true,
    align: "left", valign: "middle", margin: 0
  });

  // Sub-headline
  sl.addText("GPT-2 could complete 2-second tasks (2019) → o3 now handles ~2-hour tasks (2025)", {
    x: 0.45, y: 3.65, w: 9.1, h: 0.45,
    fontFace: FONT_BODY, fontSize: 14, color: C.ice,
    align: "left", margin: 0
  });

  // Authors / source
  sl.addText("Thomas Kwa, Ben West, Joel Becker et al. — arxiv.org/abs/2503.14499", {
    x: 0.45, y: 4.3, w: 9.1, h: 0.3,
    fontFace: FONT_BODY, fontSize: 11, color: C.slateLight, italic: true,
    align: "left", margin: 0
  });

  // Audience tag
  sl.addText("FOR: AI Safety Researchers  ·  Frontier AI Lab Leadership  ·  Policy Analysts", {
    x: 0.45, y: 4.9, w: 9.1, h: 0.28,
    fontFace: FONT_BODY, fontSize: 9.5, color: C.slate, charSpacing: 1,
    align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 2: Metric Methodology
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.offWhite };

  // Top bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: C.navyDark }, line: { color: C.navyDark }
  });
  sl.addText("METHODOLOGY", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT_BODY, fontSize: 9, color: C.teal, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  // Title
  sl.addText("A New Metric: 50% Task-Completion Time Horizon", {
    x: 0.4, y: 0.68, w: 9.2, h: 0.72,
    fontFace: FONT_HEAD, fontSize: 26, color: C.navyDark, bold: true,
    align: "left", margin: 0
  });

  // Subtitle
  sl.addText("Three-step methodology produces a human-interpretable measure of autonomous AI capability", {
    x: 0.4, y: 1.32, w: 9.2, h: 0.35,
    fontFace: FONT_BODY, fontSize: 12, color: C.slate,
    align: "left", margin: 0
  });

  // Three-step flow cards
  const steps = [
    {
      num: "1",
      head: "Diverse Task Suite",
      body: "Assemble 170 software & research tasks spanning 1 second to 8 hours of skilled human effort",
      color: C.teal
    },
    {
      num: "2",
      head: "Human Timing + AI Success",
      body: "Time 800+ human baselines (2,529 hrs total). Run each AI agent on tasks and record pass/fail",
      color: C.tealDark
    },
    {
      num: "3",
      head: "Logistic Model Fit",
      body: "Fit a logistic curve to AI success rates vs. task duration. Read off the 50% success point as the \"time horizon\"",
      color: "0D5E8A"
    }
  ];

  const stepW = 2.8;
  const stepGap = 0.25;
  const startX = 0.4;
  const stepY = 1.85;

  steps.forEach((s, i) => {
    const sx = startX + i * (stepW + stepGap);
    // Card bg
    sl.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: stepY, w: stepW, h: 2.35,
      fill: { color: C.white }, line: { color: "E2E8F0", width: 1 },
      shadow: makeShadow()
    });
    // Colored top accent
    sl.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: stepY, w: stepW, h: 0.06,
      fill: { color: s.color }, line: { color: s.color }
    });
    // Number circle (simulated with colored rect)
    sl.addShape(pres.shapes.OVAL, {
      x: sx + 0.14, y: stepY + 0.18, w: 0.48, h: 0.48,
      fill: { color: s.color }, line: { color: s.color }
    });
    sl.addText(s.num, {
      x: sx + 0.14, y: stepY + 0.18, w: 0.48, h: 0.48,
      fontFace: FONT_HEAD, fontSize: 18, color: C.white, bold: true,
      align: "center", valign: "middle", margin: 0
    });
    // Step heading
    sl.addText(s.head, {
      x: sx + 0.12, y: stepY + 0.76, w: stepW - 0.24, h: 0.45,
      fontFace: FONT_HEAD, fontSize: 14, color: C.navyDark, bold: true,
      align: "left", margin: 0
    });
    // Step body
    sl.addText(s.body, {
      x: sx + 0.12, y: stepY + 1.22, w: stepW - 0.24, h: 0.95,
      fontFace: FONT_BODY, fontSize: 11, color: C.slate,
      align: "left", valign: "top", margin: 0
    });

    // Arrow between cards
    if (i < steps.length - 1) {
      sl.addShape(pres.shapes.RECTANGLE, {
        x: sx + stepW + 0.04, y: stepY + 1.02, w: stepGap - 0.08, h: 0.06,
        fill: { color: C.teal }, line: { color: C.teal }
      });
    }
  });

  // figure_2 image
  sl.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.4, y: 4.35, w: 9.2, h: 1.1,
    sizing: { type: "contain", w: 9.2, h: 1.1 }
  });

  // Caption
  sl.addText("Figure 2 — Methodology overview (METR, 2025)", {
    x: 0.4, y: 5.3, w: 9.2, h: 0.22,
    fontFace: FONT_BODY, fontSize: 9, color: C.slateLight, italic: true,
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 3: Task Suite Overview
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  // Top bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  sl.addText("TASK SUITE", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT_BODY, fontSize: 9, color: C.navyDark, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  // Title
  sl.addText("170 Tasks Spanning 3 Seconds to 8 Hours of Human Effort", {
    x: 0.4, y: 0.68, w: 9.2, h: 0.72,
    fontFace: FONT_HEAD, fontSize: 24, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // Suite summary pills
  const suites = [
    { label: "HCAST", count: "97 tasks", range: "1 min – 30 hrs", color: C.teal },
    { label: "RE-Bench", count: "7 tasks", range: "8 hrs (all)", color: C.gold },
    { label: "SWAA", count: "66 tasks", range: "1 sec – 30 sec", color: "22C55E" }
  ];
  suites.forEach((s, i) => {
    const px = 0.4 + i * 3.15;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: px, y: 1.48, w: 2.85, h: 0.72,
      fill: { color: C.navy }, line: { color: s.color, width: 1.5 }
    });
    sl.addText(s.label, {
      x: px + 0.12, y: 1.52, w: 2.62, h: 0.28,
      fontFace: FONT_HEAD, fontSize: 14, color: s.color, bold: true,
      align: "left", margin: 0
    });
    sl.addText(`${s.count}  ·  ${s.range}`, {
      x: px + 0.12, y: 1.82, w: 2.62, h: 0.24,
      fontFace: FONT_BODY, fontSize: 10, color: C.slateLight,
      align: "left", margin: 0
    });
  });

  // Human baselines note
  sl.addText("800+ human baselines · 2,529 hours of expert labor collected", {
    x: 9.5 + 0.1 - 9.6 + 0.4, y: 1.52, w: 9.2, h: 0.28,
    fontFace: FONT_BODY, fontSize: 10, color: C.slateLight, italic: true,
    align: "right", margin: 0
  });

  // Table header
  const tableTop = 2.38;
  const colW = [1.85, 1.4, 1.2, 4.6];
  const headers = ["Task Name", "Suite", "Human Time", "Description / Example"];
  const hdrColors = [C.teal, C.teal, C.teal, C.teal];

  // Header row background
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: tableTop, w: 9.2, h: 0.38,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  let cx = 0.4;
  headers.forEach((h, i) => {
    sl.addText(h, {
      x: cx + 0.08, y: tableTop, w: colW[i] - 0.08, h: 0.38,
      fontFace: FONT_HEAD, fontSize: 10.5, color: C.navyDark, bold: true,
      align: "left", valign: "middle", margin: 0
    });
    cx += colW[i];
  });

  // Rows
  const rows = [
