const pptxgen = require("pptxgenjs");
const path = require("path");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Measuring AI Ability to Complete Long Software Tasks";
pres.author = "METR (Model Evaluation & Threat Research)";

// Palette: Deep navy dominant, ice blue support, electric teal accent
const C = {
  navyDark: "0D1B2A",    // dominant dark bg
  navy:     "1A2E45",    // secondary bg
  teal:     "00B4D8",    // accent / highlights
  tealDark: "0077A8",    // darker teal
  ice:      "CAE9FF",    // light text on dark
  white:    "FFFFFF",
  offWhite: "F0F4F8",
  slate:    "64748B",
  slateLight: "94A3B8",
  cardBg:   "142030",    // card background on dark slides
  cardBg2:  "F8FAFC",    // card background on light slides
  gold:     "F5A623",    // special callout
  green:    "22C55E",
  red:      "EF4444",
};

const FONT_HEAD = "Calibri";
const FONT_BODY = "Calibri";

const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.18 });

// ─────────────────────────────────────────────
// SLIDE 1: Title Slide
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  // Left teal accent bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.18, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Subtle grid pattern overlay (decorative rectangle)
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 0, w: 3.5, h: 5.625,
    fill: { color: "FFFFFF", transparency: 97 }, line: { color: C.teal, transparency: 85, width: 0.5 }
  });

  // METR label
  sl.addText("MODEL EVALUATION & THREAT RESEARCH (METR) — MARCH 2025", {
    x: 0.45, y: 0.38, w: 9.1, h: 0.28,
    fontFace: FONT_BODY, fontSize: 9, color: C.teal, bold: true,
    charSpacing: 2, align: "left", margin: 0
  });

  // Main title
  sl.addText("Measuring AI Ability to Complete Long Software Tasks", {
    x: 0.45, y: 0.85, w: 8.6, h: 1.55,
    fontFace: FONT_HEAD, fontSize: 36, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // Headline stat box
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 2.55, w: 7.0, h: 0.95,
    fill: { color: C.teal, transparency: 88 }, line: { color: C.teal, width: 1.5 }
  });
  sl.addText("50% TASK-COMPLETION TIME HORIZON DOUBLING EVERY ~7 MONTHS", {
    x: 0.55, y: 2.60, w: 6.8, h: 0.85,
    fontFace: FONT_HEAD, fontSize: 17, color: C.teal, bold: true,
    align: "left", valign: "middle", margin: 0
  });

  // Sub-headline
  sl.addText("GPT-2 could complete 2-second tasks (2019) → o3 now handles ~2-hour tasks (2025)", {
    x: 0.45, y: 3.65, w: 9.1, h: 0.45,
    fontFace: FONT_BODY, fontSize: 14, color: C.ice,
    align: "left", margin: 0
  });

  // Authors / source
  sl.addText("Thomas Kwa, Ben West, Joel Becker et al. — arxiv.org/abs/2503.14499", {
    x: 0.45, y: 4.3, w: 9.1, h: 0.3,
    fontFace: FONT_BODY, fontSize: 11, color: C.slateLight, italic: true,
    align: "left", margin: 0
  });

  // Audience tag
  sl.addText("FOR: AI Safety Researchers  ·  Frontier AI Lab Leadership  ·  Policy Analysts", {
    x: 0.45, y: 4.9, w: 9.1, h: 0.28,
    fontFace: FONT_BODY, fontSize: 9.5, color: C.slate, charSpacing: 1,
    align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 2: Metric Methodology
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.offWhite };

