      x: sx + 0.12, y: stepY + 1.22, w: stepW - 0.24, h: 0.95,
      fontFace: FONT_BODY, fontSize: 11, color: C.slate,
      align: "left", valign: "top", margin: 0
    });

    // Arrow between cards
    if (i < steps.length - 1) {
      sl.addShape(pres.shapes.RECTANGLE, {
        x: sx + stepW + 0.04, y: stepY + 1.02, w: stepGap - 0.08, h: 0.06,
        fill: { color: C.teal }, line: { color: C.teal }
      });
    }
  });

  // figure_2 image
  sl.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.4, y: 4.35, w: 9.2, h: 1.1,
    sizing: { type: "contain", w: 9.2, h: 1.1 }
  });

  // Caption
  sl.addText("Figure 2 — Methodology overview (METR, 2025)", {
    x: 0.4, y: 5.3, w: 9.2, h: 0.22,
    fontFace: FONT_BODY, fontSize: 9, color: C.slateLight, italic: true,
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 3: Task Suite Overview
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  // Top bar
