    fontFace: FONT_HEAD, fontSize: 22, color: C.navyDark, bold: true,
    align: "left", margin: 0
  });

  // Stat callouts row
  const stats = [
    { val: "~207", unit: "days", label: "Doubling Time" },
    { val: "R²=0.97", unit: "", label: "Exponential Fit" },
    { val: "2 sec → 110 min", unit: "", label: "GPT-2 to o3 (6 yrs)" },
  ];
  stats.forEach((s, i) => {
    const sx = 0.4 + i * 3.1;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: sx, y: 1.48, w: 2.85, h: 0.72,
