    });
  });

  // Figure 1 — main chart
  sl.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.4, y: 2.35, w: 9.2, h: 3.0,
    sizing: { type: "contain", w: 9.2, h: 3.0 }
  });

  // Caption
  sl.addText("Figure 1 — 50% task-completion time horizon vs. model release date (METR, 2025). Log scale. Doubling time ≈ 207 days, R² = 0.97.", {
    x: 0.4, y: 5.38, w: 9.2, h: 0.2,
    fontFace: FONT_BODY, fontSize: 8.5, color: C.slate, italic: true,
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 5: Per-Model Success Curves
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

