  // Right: key model callouts
  const models = [
    { name: "GPT-2",           year: "2019", horizon: "~2 sec",     color: C.slateLight },
    { name: "GPT-4 (0314)",    year: "2023", horizon: "~5 min",     color: C.teal },
    { name: "Claude 3.5 Sonnet", year: "2024", horizon: "~28 min",  color: "22C55E" },
    { name: "o1",              year: "2024", horizon: "~39 min",    color: C.gold },
    { name: "Claude 3.7 Sonnet", year: "2025", horizon: "~54 min",  color: "A78BFA" },
    { name: "o3",              year: "2025", horizon: "~1 hr 50 min", color: "F96167" },
  ];

  const rx = 6.75;
  sl.addText("50% TIME HORIZONS", {
    x: rx, y: 1.55, w: 2.85, h: 0.28,
    fontFace: FONT_BODY, fontSize: 9, color: C.teal, bold: true,
