  });

  models.forEach((m, i) => {
    const my = 1.95 + i * 0.52;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: rx, y: my, w: 0.06, h: 0.38,
      fill: { color: m.color }, line: { color: m.color }
    });
    sl.addText(m.name, {
      x: rx + 0.14, y: my, w: 2.7, h: 0.22,
      fontFace: FONT_HEAD, fontSize: 10.5, color: m.color, bold: true,
      align: "left", margin: 0
    });
    sl.addText(`${m.year}  ·  ${m.horizon}`, {
      x: rx + 0.14, y: my + 0.2, w: 2.7, h: 0.2,
      fontFace: FONT_BODY, fontSize: 9.5, color: C.slateLight,
      align: "left", margin: 0
    });
