  sl.addText("Figure 3 — Per-model success probability vs. task duration (METR, 2025).", {
    x: 0.4, y: 5.37, w: 9.2, h: 0.2,
    fontFace: FONT_BODY, fontSize: 8.5, color: C.slate, italic: true,
    align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 6: Drivers of Progress
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.offWhite };

  // Top bar
  sl.addShape(pres.shapes.RECTANGLE, {
