    align: "left", margin: 0
  });

  // 2x2 driver cards (left col) + limitations (right col)
  const drivers = [
    { icon: "→", head: "Improved Logical Reasoning", body: "Models reason through multi-step plans, debug systematically, and handle complex dependencies across long task sequences." },
    { icon: "⚙", head: "Better Tool Use", body: "Improved ability to call shell commands, write/run code, read files, and interact with APIs with greater accuracy and fewer failures." },
    { icon: "◎", head: "Reliability & Self-Awareness", body: "Frontier models more consistently recognize when they are off-track and course-correct before failures compound." },
    { icon: "↺", head: "Ability to Adapt to Mistakes", body: "When errors occur, models increasingly recover by re-trying, re-planning, or escalating—rather than silently failing." },
  ];

  drivers.forEach((d, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const dx = 0.4 + col * 4.65;
    const dy = 1.55 + row * 1.5;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: dx, y: dy, w: 4.4, h: 1.32,
