  });
  sl.addText("FORWARD EXTRAPOLATION", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT_BODY, fontSize: 9, color: C.navyDark, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  // Title
  sl.addText("Extrapolation Predicts Month-Long Task Automation by 2028–2031", {
    x: 0.4, y: 0.68, w: 9.2, h: 0.72,
    fontFace: FONT_HEAD, fontSize: 25, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // Timeline visual
  const tlY = 1.55;
  // Base line
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: tlY + 0.55, w: 9.2, h: 0.05,
    fill: { color: C.slate }, line: { color: C.slate }
  });

  // Timeline points
  const points = [
    { x: 0.8,  label: "2019", sub: "GPT-2\n~2 sec",      color: C.slateLight, dot: 0.14 },
    { x: 2.4,  label: "2023", sub: "GPT-4\n~5 min",       color: C.teal,       dot: 0.18 },
    { x: 4.15, label: "2024", sub: "o1\n~39 min",          color: C.teal,       dot: 0.18 },
    { x: 5.65, label: "2025", sub: "o3\n~1 hr 50 min",     color: C.gold,       dot: 0.22 },
    { x: 7.4,  label: "2028", sub: "Projected\n~1 month?", color: "FB923C",     dot: 0.2,  dashed: true },
    { x: 9.2,  label: "2031", sub: "Upper bound\n(slow path)", color: C.slateLight, dot: 0.16, dashed: true },
  ];

  points.forEach(p => {
    // dot
    sl.addShape(pres.shapes.OVAL, {
      x: p.x - p.dot/2, y: tlY + 0.55 - p.dot/2, w: p.dot, h: p.dot,
      fill: { color: p.color }, line: { color: p.color }
    });
    // Year label above
    sl.addText(p.label, {
      x: p.x - 0.5, y: tlY, w: 1.0, h: 0.3,
