      align: "center", valign: "top", margin: 0
    });
  });

  // Key findings below timeline
  const findings = [
    { icon: "◆", text: "~20% faster growth rate in 2023–2025 vs. full 2019–2025 trend suggests possible acceleration." },
    { icon: "◆", text: "Naive extrapolation: 1-month time horizon (167 work hours) between mid-2028 and mid-2031." },
    { icon: "◆", text: "80% time horizon is ~5× shorter than 50% horizon — tasks at the frontier of capability remain hard." },
