}

// ─────────────────────────────────────────────
// SLIDE 8: Takeaways
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  // Top teal full-width bar
  sl.addShape(pres.shapes.RECTANGLE, {
