  sl.addText("KEY TAKEAWAYS", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT_BODY, fontSize: 9, color: C.navyDark, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  // Title
  sl.addText("Exponential Autonomous Capability Growth Demands Proactive Safety Governance", {
    x: 0.4, y: 0.68, w: 9.2, h: 0.75,
    fontFace: FONT_HEAD, fontSize: 23, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // 5 numbered takeaway cards
  const takeaways = [
    { n: "1", head: "Robust & Interpretable Metric", body: "The 50% time horizon is a human-grounded, statistically robust metric for AI autonomy — R²=0.97 over 6 years and across 10+ models." },
    { n: "2", head: "Doubling Every ~7 Months", body: "The trend has been remarkably consistent since 2019, with possible acceleration since 2024 (~20% faster in 2023–2025 vs. full period)." },
    { n: "3", head: "Frontier Already at ~2 Hours", body: "o3 (2025) can autonomously complete tasks that take skilled humans ~1 hour 50 minutes — up from 2 seconds for GPT-2 in 2019." },
    { n: "4", head: "2028–2031: Month-Long Automation", body: "Naive extrapolation suggests AI reaches a 1-month (167 hr) time horizon between mid-2028 and mid-2031, enabling automation of many software projects." },
