    sl.addText(t.body, {
      x: 1.06, y: ty + 0.33, w: 8.44, h: 0.32,
      fontFace: FONT_BODY, fontSize: 10.5, color: C.slateLight,
      align: "left", valign: "top", margin: 0
    });
