    { icon: "◆", text: "Naive extrapolation: 1-month time horizon (167 work hours) between mid-2028 and mid-2031." },
    { icon: "◆", text: "80% time horizon is ~5× shorter than 50% horizon — tasks at the frontier of capability remain hard." },
    { icon: "△", text: "Caveats: trend assumes no inflection, benchmark tasks may not match real-world job distributions, external validity unverified." },
  ];

  findings.forEach((f, i) => {
    const fy = 3.05 + i * 0.55;
    const isWarning = f.icon === "△";
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: fy, w: 9.2, h: 0.44,
      fill: { color: isWarning ? "1A2820" : C.navy }, line: { color: isWarning ? "22C55E" : C.tealDark, width: 0.5 }
    });
    sl.addText(f.icon + "  " + f.text, {
      x: 0.56, y: fy + 0.04, w: 8.9, h: 0.36,
      fontFace: FONT_BODY, fontSize: 11, color: isWarning ? "86EFAC" : C.ice,
      align: "left", valign: "middle", margin: 0
    });
  });
}

// ─────────────────────────────────────────────
// SLIDE 8: Takeaways
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  // Top teal full-width bar
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  sl.addText("KEY TAKEAWAYS", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT_BODY, fontSize: 9, color: C.navyDark, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  // Title
  sl.addText("Exponential Autonomous Capability Growth Demands Proactive Safety Governance", {
    x: 0.4, y: 0.68, w: 9.2, h: 0.75,
    fontFace: FONT_HEAD, fontSize: 23, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // 5 numbered takeaway cards
  const takeaways = [
    { n: "1", head: "Robust & Interpretable Metric", body: "The 50% time horizon is a human-grounded, statistically robust metric for AI autonomy — R²=0.97 over 6 years and across 10+ models." },
    { n: "2", head: "Doubling Every ~7 Months", body: "The trend has been remarkably consistent since 2019, with possible acceleration since 2024 (~20% faster in 2023–2025 vs. full period)." },
    { n: "3", head: "Frontier Already at ~2 Hours", body: "o3 (2025) can autonomously complete tasks that take skilled humans ~1 hour 50 minutes — up from 2 seconds for GPT-2 in 2019." },
    { n: "4", head: "2028–2031: Month-Long Automation", body: "Naive extrapolation suggests AI reaches a 1-month (167 hr) time horizon between mid-2028 and mid-2031, enabling automation of many software projects." },
    { n: "5", head: "Key Limitations & Open Questions", body: "Performance degrades on unstructured tasks; external validity to real-world job distributions remains unverified. Trend extrapolations assume no structural changes." },
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.55 + i * 0.76;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: ty, w: 9.2, h: 0.68,
      fill: { color: C.navy }, line: { color: "1E3A52", width: 0.5 }
    });
    // Number badge
    sl.addShape(pres.shapes.OVAL, {
      x: 0.46, y: ty + 0.1, w: 0.46, h: 0.46,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    sl.addText(t.n, {
      x: 0.46, y: ty + 0.1, w: 0.46, h: 0.46,
      fontFace: FONT_HEAD, fontSize: 15, color: C.navyDark, bold: true,
      align: "center", valign: "middle", margin: 0
    });
    // Heading
    sl.addText(t.head, {
      x: 1.06, y: ty + 0.06, w: 3.5, h: 0.28,
      fontFace: FONT_HEAD, fontSize: 12, color: C.teal, bold: true,
      align: "left", margin: 0
    });
    // Body text
    sl.addText(t.body, {
      x: 1.06, y: ty + 0.33, w: 8.44, h: 0.32,
      fontFace: FONT_BODY, fontSize: 10.5, color: C.slateLight,
      align: "left", valign: "top", margin: 0
    });
  });

  // Bottom source line
  sl.addText("Source: Kwa et al. (METR, March 2025) — arxiv.org/abs/2503.14499", {
    x: 0.4, y: 5.38, w: 9.2, h: 0.2,
    fontFace: FONT_BODY, fontSize: 8.5, color: C.slate, italic: true,
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────
// WRITE FILE
// ─────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✓ Saved to /app/output/final_deck.pptx"))
  .catch(err => { console.error("ERROR:", err); process.exit(1); });

