const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Measuring AI Ability to Complete Long Software Tasks";
pres.author = "METR (Model Evaluation & Threat Research)";

const C = {
  navyDark:   "0D1B2A",
  navy:       "1A2E45",
  teal:       "00B4D8",
  tealDark:   "0077A8",
  ice:        "CAE9FF",
  white:      "FFFFFF",
  offWhite:   "F0F4F8",
  slate:      "64748B",
  slateLight: "94A3B8",
  cardBg:     "142030",
  gold:       "F5A623",
  green:      "22C55E",
};

const FONT = "Calibri";
const makeShadow = () => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.18 });

// ─────────────────────────────────────────────
// SLIDE 1: Title Slide
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  // Left teal accent bar (x:0 so it's definitely at the edge)
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.22, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // METR label
  sl.addText("MODEL EVALUATION & THREAT RESEARCH (METR) — MARCH 2025", {
    x: 0.45, y: 0.38, w: 9.1, h: 0.28,
    fontFace: FONT, fontSize: 9, color: C.teal, bold: true,
    charSpacing: 2, align: "left", margin: 0
  });

  // Main title
  sl.addText("Measuring AI Ability to Complete Long Software Tasks", {
    x: 0.45, y: 0.80, w: 9.1, h: 1.6,
    fontFace: FONT, fontSize: 36, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // Headline stat box — full width so no dead zone
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.45, y: 2.52, w: 9.1, h: 0.9,
    fill: { color: C.teal, transparency: 88 }, line: { color: C.teal, width: 1.5 }
  });
  sl.addText("50% TASK-COMPLETION TIME HORIZON DOUBLING EVERY ~7 MONTHS", {
    x: 0.55, y: 2.56, w: 8.9, h: 0.82,
    fontFace: FONT, fontSize: 17, color: C.teal, bold: true,
    align: "left", valign: "middle", margin: 0
  });

  // Sub-headline
  sl.addText("GPT-2 completed 2-second tasks (2019) → o3 now handles ~2-hour tasks (2025)", {
    x: 0.45, y: 3.58, w: 9.1, h: 0.42,
    fontFace: FONT, fontSize: 13.5, color: C.ice,
    align: "left", margin: 0
  });

  // Authors / source — brighter color for contrast
  sl.addText("Thomas Kwa, Ben West, Joel Becker et al. — arxiv.org/abs/2503.14499", {
    x: 0.45, y: 4.12, w: 9.1, h: 0.3,
    fontFace: FONT, fontSize: 11, color: C.slateLight, italic: true,
    align: "left", margin: 0
  });

  // Audience tag — use ice color for contrast
  sl.addText("FOR: AI Safety Researchers  ·  Frontier AI Lab Leadership  ·  Policy Analysts", {
    x: 0.45, y: 4.62, w: 9.1, h: 0.3,
    fontFace: FONT, fontSize: 10, color: C.ice, charSpacing: 1,
    align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 2: Methodology
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.offWhite };

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: C.navyDark }, line: { color: C.navyDark }
  });
  sl.addText("METHODOLOGY", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT, fontSize: 9, color: C.teal, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  sl.addText("A New Metric: 50% Task-Completion Time Horizon", {
    x: 0.4, y: 0.65, w: 9.2, h: 0.65,
    fontFace: FONT, fontSize: 26, color: C.navyDark, bold: true,
    align: "left", margin: 0
  });

  sl.addText("Three-step methodology produces a human-interpretable measure of autonomous AI capability", {
    x: 0.4, y: 1.34, w: 9.2, h: 0.32,
    fontFace: FONT, fontSize: 12, color: C.slate,
    align: "left", margin: 0
  });

  // Three-step flow cards — reduced height to make room below
  const steps = [
    {
      num: "1",
      head: "Diverse Task Suite",
      body: "Assemble 170 software & research tasks spanning 1 second to 8 hours of skilled human effort",
      color: C.teal
    },
    {
      num: "2",
      head: "Human Timing + AI Testing",
      body: "Time 800+ human baselines (2,529 hrs total). Run each AI agent on tasks and record pass/fail results",
      color: C.tealDark
    },
    {
      num: "3",
      head: "Logistic Model Fit",
      body: "Fit logistic curve to AI success rates vs. task duration. Read off the 50% success point as the \"time horizon\"",
      color: "0D5E8A"
    }
  ];

  const stepW = 2.85;
  const stepGap = 0.22;
  const startX = 0.38;
  const stepY = 1.78;
  const stepH = 2.0;

