      x: rx + 0.14, y: my + 0.20, w: 2.76, h: 0.20,
      fontFace: FONT, fontSize: 9.5, color: C.slateLight,
      align: "left", margin: 0
    });
  });

  sl.addText("Figure 3 — Per-model success probability vs. task duration (METR, 2025).", {
    x: 0.4, y: 5.33, w: 9.2, h: 0.20,
    fontFace: FONT, fontSize: 8.5, color: C.slateLight, italic: true,
    align: "left", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 6: Drivers of Progress
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.offWhite };

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: C.navyDark }, line: { color: C.navyDark }
  });
  sl.addText("CAPABILITY DRIVERS", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT, fontSize: 9, color: C.teal, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  sl.addText("Reasoning, Tool Use, and Error Recovery Drive Time Horizon Growth", {
    x: 0.4, y: 0.65, w: 9.2, h: 0.70,
    fontFace: FONT, fontSize: 25, color: C.navyDark, bold: true,
    align: "left", margin: 0
  });

  const drivers = [
    { head: "Improved Logical Reasoning",  body: "Models reason through multi-step plans, debug systematically, and handle complex dependencies across long task sequences." },
    { head: "Better Tool Use",             body: "Improved ability to call shell commands, write/run code, read files, and interact with APIs with greater accuracy and fewer failures." },
    { head: "Reliability & Self-Awareness",body: "Frontier models more consistently recognize when they are off-track and course-correct before failures compound." },
    { head: "Ability to Adapt to Mistakes",body: "When errors occur, models increasingly recover by re-trying, re-planning, or escalating — rather than silently failing." },
  ];

  // Fixed card heights so all are equal
  const cardW = 4.35;
  const cardH = 1.3;
  const cardGap = 0.2;
  drivers.forEach((d, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const dx = 0.4 + col * (cardW + cardGap);
    const dy = 1.48 + row * (cardH + 0.18);
    sl.addShape(pres.shapes.RECTANGLE, {
      x: dx, y: dy, w: cardW, h: cardH,
      fill: { color: C.white }, line: { color: "E2E8F0", width: 1 },
      shadow: makeShadow()
    });
    sl.addShape(pres.shapes.RECTANGLE, {
      x: dx, y: dy, w: 0.07, h: cardH,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    sl.addText(d.head, {
      x: dx + 0.18, y: dy + 0.10, w: cardW - 0.26, h: 0.30,
      fontFace: FONT, fontSize: 12.5, color: C.navyDark, bold: true,
      align: "left", margin: 0
    });
    sl.addText(d.body, {
      x: dx + 0.18, y: dy + 0.42, w: cardW - 0.26, h: 0.80,
      fontFace: FONT, fontSize: 10.5, color: C.slate,
      align: "left", valign: "top", margin: 0
    });
  });

  // Limitation band — ensure ≥ 0.5" from bottom
  const limY = 4.38;
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: limY, w: 9.2, h: 0.76,
    fill: { color: "FFF7ED" }, line: { color: "FB923C", width: 1.2 }
  });
  sl.addText("LIMITATION:", {
    x: 0.58, y: limY + 0.08, w: 1.35, h: 0.28,
    fontFace: FONT, fontSize: 11, color: "EA580C", bold: true,
    align: "left", margin: 0
  });
  sl.addText("Performance is notably lower on less structured, 'messier' tasks. External validity is an open question — the benchmark may not perfectly represent the average segment of real-world intellectual labor.", {
    x: 1.9, y: limY + 0.08, w: 7.55, h: 0.58,
    fontFace: FONT, fontSize: 10.5, color: "92400E",
    align: "left", valign: "top", margin: 0
  });
}

// ─────────────────────────────────────────────
// SLIDE 7: Extrapolation
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: C.gold }, line: { color: C.gold }
  });
  sl.addText("FORWARD EXTRAPOLATION", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT, fontSize: 9, color: C.navyDark, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  sl.addText("Extrapolation Predicts Month-Long Task Automation by 2028–2031", {
    x: 0.4, y: 0.65, w: 9.2, h: 0.70,
    fontFace: FONT, fontSize: 24, color: C.white, bold: true,
    align: "left", margin: 0
  });

  // Timeline
  const tlY = 1.48;
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.55, y: tlY + 0.50, w: 8.9, h: 0.05,
    fill: { color: C.slate }, line: { color: C.slate }
  });

  const points = [
    { x: 0.85,  label: "2019", sub: "GPT-2\n~2 sec",           color: C.slateLight, dotR: 0.12, dash: false },
    { x: 2.45,  label: "2023", sub: "GPT-4\n~5 min",            color: C.teal,       dotR: 0.16, dash: false },
    { x: 4.10,  label: "2024", sub: "o1\n~39 min",              color: C.teal,       dotR: 0.16, dash: false },
    { x: 5.70,  label: "2025", sub: "o3\n~1 hr 50 min",         color: C.gold,       dotR: 0.20, dash: false },
    { x: 7.35,  label: "2028", sub: "Projected:\n~1 month?",    color: "FB923C",     dotR: 0.18, dash: true  },
    { x: 9.35,  label: "2031", sub: "Upper bound\n(slow path)", color: C.slateLight, dotR: 0.14, dash: true  },
  ];

  points.forEach(p => {
    sl.addShape(pres.shapes.OVAL, {
      x: p.x - p.dotR, y: tlY + 0.50 - p.dotR, w: p.dotR * 2, h: p.dotR * 2,
      fill: { color: p.color }, line: { color: p.color }
    });
    sl.addText(p.label, {
      x: p.x - 0.5, y: tlY, w: 1.0, h: 0.30,
      fontFace: FONT, fontSize: 11, color: p.color, bold: true,
      align: "center", margin: 0
    });
    sl.addText(p.sub, {
      x: p.x - 0.65, y: tlY + 0.72, w: 1.3, h: 0.52,
      fontFace: FONT, fontSize: 9.5, color: p.dash ? C.slate : C.slateLight,
      align: "center", valign: "top", margin: 0
    });
  });

  // Finding rows
  const findings = [
    { text: "~20% faster growth in 2023–2025 vs. the full 2019–2025 trend suggests possible acceleration.",                                                   warn: false },
    { text: "Naive extrapolation: 1-month time horizon (167 work hours) between mid-2028 and mid-2031.",                                                       warn: false },
    { text: "80% time horizon is ~5× shorter than the 50% horizon — tasks at the capability frontier remain hard.",                                            warn: false },
    { text: "Caveats: Trend assumes no inflection. Benchmark tasks may not match real-world job distributions. External validity unverified.",                  warn: true  },
  ];

  findings.forEach((f, i) => {
    const fy = 3.08 + i * 0.52;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: fy, w: 9.2, h: 0.44,
      fill: { color: f.warn ? "111E14" : C.navy },
      line: { color: f.warn ? C.green : C.tealDark, width: 0.5 }
    });
    sl.addText((f.warn ? "⚠  " : "◆  ") + f.text, {
      x: 0.56, y: fy + 0.04, w: 8.88, h: 0.36,
      fontFace: FONT, fontSize: 10.5, color: f.warn ? "86EFAC" : C.ice,
      align: "left", valign: "middle", margin: 0
    });
  });
}

// ─────────────────────────────────────────────
// SLIDE 8: Takeaways
// ─────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navyDark };

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.55,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  sl.addText("KEY TAKEAWAYS", {
    x: 0.4, y: 0, w: 9.2, h: 0.55,
    fontFace: FONT, fontSize: 9, color: C.navyDark, bold: true,
    charSpacing: 3, align: "left", valign: "middle", margin: 0
  });

  sl.addText("Exponential Autonomous Capability Growth Demands Proactive Safety Governance", {
    x: 0.4, y: 0.65, w: 9.2, h: 0.70,
    fontFace: FONT, fontSize: 22, color: C.white, bold: true,
    align: "left", margin: 0
  });

  const takeaways = [
    { n: "1", head: "Robust & Interpretable Metric",     body: "50% time horizon is a human-grounded, statistically robust metric for AI autonomy — R²=0.97 over 6 years across 10+ models." },
    { n: "2", head: "Doubling Every ~7 Months",          body: "The trend has been remarkably consistent since 2019, with possible acceleration since 2024 (~20% faster in 2023–2025 vs. full period)." },
    { n: "3", head: "Frontier Already at ~2 Hours",      body: "o3 (2025) can autonomously complete tasks taking skilled humans ~1 hr 50 min — up from 2 seconds for GPT-2 in 2019." },
    { n: "4", head: "2028–2031: Month-Long Automation",  body: "Extrapolation suggests AI reaches a 1-month (167 hr) time horizon between mid-2028 and mid-2031, enabling automation of many software projects." },
    { n: "5", head: "Limitations & Open Questions",      body: "Performance degrades on unstructured tasks; external validity to real-world job distributions remains unverified. Trend extrapolations assume no structural changes." },
  ];

  takeaways.forEach((t, i) => {
    const ty = 1.46 + i * 0.72;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: ty, w: 9.2, h: 0.65,
      fill: { color: C.navy }, line: { color: "1E3A52", width: 0.5 }
    });
    sl.addShape(pres.shapes.OVAL, {
      x: 0.46, y: ty + 0.10, w: 0.44, h: 0.44,
      fill: { color: C.teal }, line: { color: C.teal }
    });
    sl.addText(t.n, {
      x: 0.46, y: ty + 0.10, w: 0.44, h: 0.44,
      fontFace: FONT, fontSize: 14, color: C.navyDark, bold: true,
      align: "center", valign: "middle", margin: 0
    });
    sl.addText(t.head, {
      x: 1.06, y: ty + 0.06, w: 3.3, h: 0.28,
      fontFace: FONT, fontSize: 12, color: C.teal, bold: true,
      align: "left", margin: 0
    });
    sl.addText(t.body, {
      x: 1.06, y: ty + 0.32, w: 8.44, h: 0.30,
      fontFace: FONT, fontSize: 10.5, color: C.slateLight,
      align: "left", valign: "top", margin: 0
    });
  });

  // Source line — use ice for readable contrast, 0.5" from bottom
  sl.addText("Source: Kwa et al. (METR, March 2025) — arxiv.org/abs/2503.14499", {
    x: 0.4, y: 5.16, w: 9.2, h: 0.24,
    fontFace: FONT, fontSize: 9, color: C.slateLight, italic: true,
    align: "center", margin: 0
  });
}

// ─────────────────────────────────────────────
// WRITE FILE
// ─────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Saved to /app/output/final_deck.pptx"))
  .catch(err => { console.error("ERROR:", err); process.exit(1); });

