    const rowBg = ri % 2 === 0 ? C.navy : C.cardBg;
    sl.addShape(pres.shapes.RECTANGLE, {
      x: 0.4, y: ry, w: 9.2, h: rowH,
      fill: { color: rowBg }, line: { color: "1E3A52", width: 0.5 }
    });
    let cx2 = 0.4;
    row.forEach((cell, ci) => {
      const isSuite = ci === 1;
      const tc = isSuite ? (suiteColorsMap[cell] || C.white)
                : ci === 0 ? C.ice
                : ci === 2 ? C.gold
                : C.slateLight;
      sl.addText(cell, {
        x: cx2 + 0.08, y: ry + 0.03, w: colW[ci] - 0.12, h: rowH - 0.06,
        fontFace: FONT, fontSize: isSuite ? 10 : 10.5,
        color: tc, bold: isSuite,
        align: "left", valign: "middle", margin: 0
      });
      cx2 += colW[ci];
    });
  });

  // Footer with adequate bottom margin (slide h = 5.625)
  sl.addText("Task durations reflect skilled human professional completion times. HCAST = Human-Computer Autonomy Software Tasks.", {
    x: 0.4, y: 5.28, w: 9.2, h: 0.24,
    fontFace: FONT, fontSize: 8.5, color: C.slate, italic: true,
    align: "left", margin: 0
  });
}

